import os
import time

import requests

from taf.cloud.cbam import exception


class CbamResponse(object):
    def __init__(self, raw_response):
        try:
            self.data = raw_response.json()
        except (ValueError, AttributeError):
            self.data = None
        self.status_code = raw_response.status_code
        try:
            if self.data is None:
                self.data = {}
            self.data['operationId'] = os.path.basename(raw_response.headers['Location'])
        except (TypeError, KeyError):
            pass

    def convert(self,
                fail_class,
                success_class,
                success_codes):
        objectified_result = None

        if success_class is not None and self.status_code in success_codes:
            objectified_result = success_class.from_response_dict(self.data)
        elif fail_class is not None and self.status_code not in success_codes:
            objectified_result = fail_class.from_response_dict(self.data)

        return objectified_result

    def convert_list(self,
                     fail_class,
                     success_class,
                     success_codes):
        if success_class is not None and self.status_code in success_codes:
            result = []
            for r in self.data:
                objectified_result = success_class.from_response_dict(r)
                result.append(objectified_result)
            return result

        elif fail_class is not None:
            objectified_result = fail_class.from_response_dict(self.data)
            return objectified_result
        else:
            return self.data


class CbamSession(object):
    def __init__(self, cbam_ip, verify):
        self.__verify = verify
        self.__cbam_ip = cbam_ip

        self.__client_id = None
        self.__client_secret = None
        self.__token = SessionToken()

    # TODO: check if it can be improved by requests_oauthlib
    def authenticate(self, client_id, client_secret):
        self.__client_id = client_id
        self.__client_secret = client_secret

        url, body, headers = self.__get_request_parts(grant_type='client_credentials')
        response = requests.post(url,
                                 headers=headers,
                                 data=body,
                                 verify=self.__verify)

        response_json = response.json()
        if response_json.get('error'):
            error = response_json.get('error')
            error_description = response_json.get('error_description')
            raise exception.SessionException('{}. Reason of failure: {}'.format(error, error_description))

        self.__token.parse_token(response_json)

    def send_request(self,
                     method,
                     endpoint,
                     api_version=None,
                     content_type='application/json',
                     **options):
        if not self.__token:
            raise RuntimeError("no token available, call authenticate first")

        method = getattr(requests, method)
        url = 'https://{ip}/{end}'.format(ip=self.__cbam_ip, end=endpoint)
        auth_header = self._create_header(api_version, content_type)
        options.update({'headers': auth_header, 'verify': self.__verify})

        response = method(url, **options)
        response = self.get_verified_response(response)

        return response

    def _create_header(self, api_version=None, content_type='application/json'):
        access_token = self.__get_valid_access_token()
        auth_header = {'Authorization': 'bearer {}'.format(access_token)}

        if api_version is not None:
            auth_header['Nokia-VNFM-API-Version'] = api_version
        if content_type is not None:
            auth_header['Content-Type'] = content_type

        return auth_header

    def __get_valid_access_token(self):
        if not self.__token.is_token_valid():
            self.__update_access_token()

        return self.__token.access_token

    def __update_access_token(self):
        url, body, headers = self.__get_request_parts(grant_type='refresh_token')
        response = requests.post(url,
                                 headers=headers,
                                 data=body,
                                 verify=self.__verify)

        response_data = response.json()
        self.__token.parse_token(response_data)

    def __get_request_parts(self, grant_type):
        url = 'https://{ip}/{end}'.format(ip=self.__cbam_ip,
                                          end=self.__token.token_endpoint)
        headers = {'Content-Type': 'application/x-www-form-urlencoded'}
        body = 'grant_type={grant_type}&client_id={id}&client_secret={secret}'.format(
            grant_type=grant_type,
            id=self.__client_id,
            secret=self.__client_secret)

        if grant_type == 'refresh_token':
            body += '&refresh_token={rt}'.format(rt=self.__token.refresh_token)

        return url, body, headers

    def get_verified_response(self, response):
        try:
            response_json = response.json()
        except ValueError:
            response_json = None
        if isinstance(response_json, list):
            for item in response_json:
                self._check_response(item, response)
        else:
            self._check_response(response_json, response)

        result = CbamResponse(response)
        return result

    def _check_response(self, response_json, response):
        vnf_exception = self._get_exception_class(response)
        if vnf_exception is not None:
            if response_json is not None:
                title = response_json.get('title', "")
                detail = response_json.get('detail', "")
                exception_message = (title + '\n' + detail) if title else detail
            else:
                exception_message = None
            raise vnf_exception(exception_message)

    def _get_exception_class(self, resp):
        codes_exceptions = {400: exception.BadRequestException,
                            401: exception.UnauthorizedException,
                            403: exception.ForbiddenAccessException,
                            404: exception.NotFoundException,
                            405: exception.MethodNotAllowedException,
                            406: exception.NotApplicableException,
                            409: exception.ConflictException,
                            422: exception.UnprocessableEntityException,
                            500: exception.InternalServerErrorException,
                            503: exception.ServiceUnavailableException}
        vnf_exception = codes_exceptions.get(resp.status_code, None)

        return vnf_exception

    def is_session_open(self):
        return self.__token.is_session_open()


class SessionToken(object):
    def __init__(self):
        self.access_token = None
        self.access_token_set_time = None
        self.access_token_expiry_time = None  # in seconds
        self.refresh_token = None
        self.session_expiry_time = None  # in seconds
        self.__token_endpoint = 'auth/realms/cbam/protocol/openid-connect/token'

    @property
    def token_endpoint(self):
        return self.__token_endpoint

    def __bool__(self):
        return bool(self.access_token and
                    self.access_token_set_time and
                    self.access_token_expiry_time and
                    self.refresh_token)

    __nonzero__ = __bool__

    def parse_token(self, response):
        self.refresh_token = response['refresh_token']
        self.access_token = response['access_token']
        self.access_token_expiry_time = response['expires_in']  # in seconds
        self.session_expiry_time = response['refresh_expires_in']
        self.access_token_set_time = time.time()

    def is_token_valid(self):
        time_passed = time.time() - self.access_token_set_time
        return time_passed < self.access_token_expiry_time

    def is_session_open(self):
        time_passed = time.time() - self.access_token_set_time
        return time_passed < self.session_expiry_time
